# Mock helper for test purposes
def calculate_stock_volatility(prices):
    """Returns sample volatility: standard deviation of daily price changes."""
    if len(prices) < 2:
        return 0.0
    diffs = [abs(prices[i+1] - prices[i]) for i in range(len(prices)-1)]
    mean = sum(diffs) / len(diffs)
    variances = [(d - mean) ** 2 for d in diffs]
    std = (sum(variances) / len(variances)) ** 0.5
    return std

def portfolio_risk_assessment(stocks):
    '''
    Takes a dict where keys are stock names and values have 'prices' list and 'allocation' float.
    For each stock, call calculate_stock_volatility(prices), multiply by allocation, sum all weighted volatilities.
    Returns: float representing total portfolio risk.
    '''
    total_risk = 0.0
    for stock in stocks:
        data = stocks[stock]
        weighted_volatility = calculate_stock_volatility(data['prices']) * data['allocation']
        total_risk += weighted_volatility
    return total_risk

